 ei.participantBodies=[b for b in ac.bRepBodies if b.name in ['AZN_C5_abad_spacer','AZN_C5_abad_disc']]
 ac.features.extrudeFeatures.add(ei).name='AZN_C5_abad_mount_holes';s.isLightBulbOn=False
 def bd(n):return next(b for b in ac.bRepBodies if b.name==n)
